use super::{
    ACTOR_HELP_TOPIC_ACK, ACTOR_HELP_TOPIC_INBOX, ACTOR_HELP_TOPIC_PERMISSION_REVIEW_RESPOND,
    ACTOR_HELP_TOPIC_RECEIVE, ACTOR_HELP_TOPIC_SEND, ACTOR_HELP_TOPIC_TEAM_THREAD_OPEN,
    ACTOR_HELP_TOPIC_TEAM_THREAD_REPLY, ACTOR_HELP_TOPICS,
};
use crate::actor_runtime_env::{
    ACTOR_RUNTIME_ACTOR_ID_ENV, ACTOR_RUNTIME_AGENT_ID_ENV, ACTOR_RUNTIME_CHANNEL_ENV,
    ACTOR_RUNTIME_CURRENT_RUN_ID_ENV, ACTOR_RUNTIME_TEAM_ID_ENV,
};

pub(super) fn is_help_flag(arg: &str) -> bool {
    matches!(arg.trim(), "--help" | "-h")
}

pub(super) fn is_help_subcommand(arg: &str) -> bool {
    arg.trim() == "help"
}

fn normalize_help_topic(raw: &str) -> String {
    raw.trim()
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .flat_map(|ch| ch.to_lowercase())
        .collect()
}

pub(super) fn resolve_actor_help_topic(raw: &str) -> anyhow::Result<&'static str> {
    let normalized = normalize_help_topic(raw);
    anyhow::ensure!(
        !normalized.is_empty(),
        "actor help topic must be a non-empty string"
    );
    if normalized == "teamtaskget" {
        return Ok("team-task-show");
    }
    let mut matches = ACTOR_HELP_TOPICS
        .iter()
        .copied()
        .filter(|topic| {
            let topic_normalized = normalize_help_topic(topic);
            topic_normalized == normalized || topic_normalized.starts_with(&normalized)
        })
        .collect::<Vec<_>>();
    matches.sort_unstable();
    matches.dedup();
    match matches.as_slice() {
        [topic] => Ok(*topic),
        [] => Err(anyhow::anyhow!(
            "unknown actor help topic '{}'; try one of: {}",
            raw.trim(),
            ACTOR_HELP_TOPICS.join(", ")
        )),
        _ => Err(anyhow::anyhow!(
            "ambiguous actor help topic '{}'; matches: {}",
            raw.trim(),
            matches.join(", ")
        )),
    }
}

pub(super) fn actor_usage() -> String {
    format!(
        "Usage:\n  agenthub actor help [topic]\n  agenthub actor [--json] team-members [--team-id <team_id>] [--run-id <run_id>]\n  agenthub actor [--json] team-tasks [--team-id <team_id>] [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--limit <n>] [--status <all|open|in_progress|waiting|in_review|completed|canceled>] [--task-id <task_id>] [--assigned-member-id <member_id>] [--topic <topic>] [--include-shared-thread]\n  agenthub actor [--json] team-task-create --title <title> [--team-id <team_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--status <open|in_progress|waiting|in_review|completed|canceled>] [--topic <topic>] [--context-json <json> | --context-json-file <path>]\n  agenthub actor [--json] team-task-show --task-id <task_id> [--team-id <team_id>] [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--message-limit <n>]\n  agenthub actor [--json] team-task-update --task-id <task_id> [--task-id <task_id> ...] [--status <open|in_progress|waiting|in_review|completed|canceled>] [--assigned-member-id <member_id> | --unassign] [--context-json <json> | --context-json-file <path> | --context-file <path> | --context-merge-json <json> | --context-merge-json-file <path> | --context-merge-file <path>] [--team-id <team_id>] [--actor-id <actor_id> | --agent-id <agent_id>]\n  agenthub actor [--json] team-task-note (--task-id <task_id> | --shared-thread) [--kind <comment|decision|result>] --text <markdown> [--team-id <team_id>] [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>]\n  agenthub actor [--json] team-channel-create --team-id <team_id> --channel-id <channel_id> [--description <text>] [--actor-id <actor_id> | --agent-id <agent_id>]\n  agenthub actor [--json] team-channel-delete --team-id <team_id> --channel-id <channel_id> [--actor-id <actor_id> | --agent-id <agent_id>]\n  agenthub actor [--json] team-thread-open --root-message-id <message_id> [--channel-id <channel_id> | --shared] [--team-id <team_id>] [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>]\n  agenthub actor [--json] team-thread-reply --root-message-id <message_id> (--text <markdown> | --text-file <path>) [--channel-id <channel_id> | --shared] [--team-id <team_id>] [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>]\n  agenthub actor [--json] team-step-transition --step-id <step_id> --action <start|continue|complete|input_required|resume|fail> [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--runtime-handle-id <session_id>] [--output-json <json> | --output-json-file <path>] [--input-json <json> | --input-json-file <path>] [--reason <text> | --reason-file <path>] [--error-text <text> | --error-text-file <path>]\n  agenthub actor [--json] team-step-decision --step-id <step_id> [--decision-json <json> | --decision-json-file <path>] [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--runtime-handle-id <session_id>]\n  agenthub actor [--json] inbox [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--limit <n>] [--after-id <id>] [--include-delivered]\n  agenthub actor [--json] receive [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--limit <n>] [--after-id <id>]\n  agenthub actor [--json] ack (--message-id <id> [--message-id <id> ...] | <id> [<id> ...]) [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>]\n  agenthub actor [--json] send ((--to-actor-id <actor_id> | --to-agent-id <agent_id> | --to <actor_id> | --direct <actor_id>) | (--channel-id <channel_id> | --shared)) (--text <markdown> | --text-file <path> | --payload-json <json> | --payload-file <path>) [--mention <actor_id> ...] [--mention-actor-id <actor_id> ...] [--run-id <run_id>] [--from-actor-id <actor_id> | --from-agent-id <agent_id>] [--channel <name>] [--transport <local|remote>] [--route-json <json>] [--idempotency-key <key>] [--allow-duplicate]\n  agenthub actor [--json] time-trigger-set --delay-seconds <seconds> --message <text> [--actor-id <actor_id> | --agent-id <agent_id>]\n  agenthub actor [--json] time-trigger-list [--actor-id <actor_id> | --agent-id <agent_id>] [--limit <n>]\n  agenthub actor [--json] time-trigger-cancel --trigger-id <trigger_id> [--actor-id <actor_id> | --agent-id <agent_id>]\n  agenthub actor [--json] permission-review-respond --permission-id <id> [--permission-id <id> ...] [--team-id <team_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--option-id <option_id> | --outcome cancelled]\n\nQuick start:\n  agenthub actor receive\n  agenthub actor inbox --include-delivered\n  agenthub actor send --to reviewer --text-file <path>\n  agenthub actor send --shared --text \"@reviewer please validate the contract\"\n  agenthub actor team-task-note --shared-thread --kind result --text <markdown>\n  agenthub actor team-channel-create --team-id <team_id> --channel-id review --description \"Review lane\"\n  agenthub actor team-thread-open --shared --root-message-id <message_id>\n  agenthub actor team-thread-reply --shared --root-message-id <message_id> --text \"I agree with this point\"\n\nHelp:\n  `agenthub actor help receive`\n  `agenthub actor help team-task-show`\n  `agenthub actor help team-thread-open`\n  `agenthub actor help team-thread-reply`\n  `agenthub actor help team-step-transition`\n  `agenthub actor help team-step-decision`\n  `agenthub actor help perm`\n  `agenthub actor receive --help`\n  Topic matching is fuzzy for help only; command execution remains strict.\n\nOutput:\n  Read-heavy results (`team-members`, `team-tasks`, `team-task-show`, `team-thread-open`, `team-thread-reply`, `inbox`, `receive`, `time-trigger-list`) default to TOON on stdout.\n  Human-oriented team/task/channel confirmations (`team-channel-create`, `team-channel-delete`, `team-task-create`, `team-task-update`, `team-task-note`, `time-trigger-set`, `time-trigger-cancel`) default to TOON on stdout.\n  Machine-oriented confirmations (`ack`, `send`, `permission-review-respond`, `team-step-transition`, `team-step-decision`) default to compact JSON for script compatibility.\n  `--json` forces JSON output for all structured success results.\n\nMailbox note:\n  `actor inbox` is read-only and should be used for inspection/debugging.\n  Use `actor receive` when the current actor is ready to accept and consume pending mailbox work.\n  Keep `actor ack` for repair, recovery, or manual compensation flows.\n  Use `team-task-note --shared-thread` for human-visible shared progress updates when you do not want to route through run-scoped mailbox send.\n\nEnvironment fallback:\n  {}\n  {}\n  {}\n  {}\n  {}\n",
        ACTOR_RUNTIME_TEAM_ID_ENV,
        ACTOR_RUNTIME_CURRENT_RUN_ID_ENV,
        ACTOR_RUNTIME_ACTOR_ID_ENV,
        ACTOR_RUNTIME_AGENT_ID_ENV,
        ACTOR_RUNTIME_CHANNEL_ENV,
    )
}

pub(super) fn actor_topic_usage(topic: &str) -> String {
    match topic {
        ACTOR_HELP_TOPIC_INBOX => "Usage:\n  agenthub actor inbox [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--limit <n>] [--after-id <id>] [--include-delivered]\n\nExamples:\n  agenthub actor inbox\n  agenthub actor inbox --include-delivered\n\nNotes:\n  `actor inbox` is read-only by default.\n  Use it to inspect unread or historical mailbox state without mutating delivery status.\n  In team runtime, omitting `--actor-id` still uses actor runtime env fallback.\n  If `current_run_id` is missing but `team_id` is available, inbox now falls back to the canonical shared-thread mailbox run for that team.\n".to_string(),
        ACTOR_HELP_TOPIC_RECEIVE => "Usage:\n  agenthub actor receive [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--limit <n>] [--after-id <id>]\n\nExamples:\n  agenthub actor receive\n  agenthub actor receive --limit 20\n  agenthub actor receive --run-id <run_id> --actor-id <actor_id>\n\nNotes:\n  `actor receive` accepts pending mailbox messages for the current actor and acknowledges the accepted items.\n  Returned messages reflect the accepted delivery state, and `pending_count` reports the remaining unread count after acceptance.\n  Use `actor inbox` instead when you only need a read-only snapshot.\n  In team runtime, omitting `--actor-id` still uses actor runtime env fallback.\n  If `current_run_id` is missing but `team_id` is available, receive falls back to the canonical shared-thread mailbox run for that team.\n".to_string(),
        ACTOR_HELP_TOPIC_ACK => "Usage:\n  agenthub actor ack (--message-id <id> [--message-id <id> ...] | <id> [<id> ...]) [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>]\n\nExamples:\n  agenthub actor ack 123\n  agenthub actor ack 123 124\n  agenthub actor ack --message-id 123 --message-id 124\n  agenthub actor ack --run-id <run_id> --actor-id <actor_id> 123\n\nNotes:\n  `actor ack` is the manual repair/compensation path for mailbox delivery state.\n  The JSON response now includes `status_changed` so callers can distinguish a real `pending -> delivered` transition from an idempotent/no-op ack.\n  Positional ids and repeated `--message-id` flags are equivalent.\n  In team runtime, omitting `--run-id` lets AgentHub try the current actor runtime scope first, then fall back to the unique active Team run for the current team when possible.\n  If multiple active Team runs exist, `actor ack` will fail with concrete candidate hints and require `--run-id`.\n".to_string(),
        ACTOR_HELP_TOPIC_SEND => "Usage:\n  agenthub actor send ((--to-actor-id <actor_id> | --to-agent-id <agent_id> | --to <actor_id> | --direct <actor_id>) | (--channel-id <channel_id> | --shared)) (--text <markdown> | --text-file <path> | --payload-json <json> | --payload-file <path>) [--mention <actor_id> ...] [--mention-actor-id <actor_id> ...] [--run-id <run_id>] [--from-actor-id <actor_id> | --from-agent-id <agent_id>] [--channel <name>] [--transport <local|remote>] [--route-json <json>] [--idempotency-key <key>] [--allow-duplicate]\n\nExamples:\n  agenthub actor send --to reviewer --text-file .agenthubmemory/mailbox/outbox/review.md\n  agenthub actor send --direct reviewer --text \"please validate the patch\"\n  agenthub actor send --shared --text-file .agenthubmemory/mailbox/outbox/channel-update.md\n  agenthub actor send --shared --text \"@reviewer please validate the contract\"\n  agenthub actor send --shared --text \"@reviewer @worker please review the dependency tradeoff\"\n  agenthub actor send --to-actor-id reviewer --payload-file .agenthubmemory/mailbox/outbox/review.json\n\nNotes:\n  Prefer `--text-file` for multi-line or reusable mailbox messages so `agenthub` stays at the command prefix.\n  Use `--text` only for short inline coordination notes.\n  Use `--payload-json` or `--payload-file` only for structured machine-readable envelopes.\n  Direct mailbox targets must use canonical Team `spec.members[].member_id` values; role aliases such as `coordinator` are rejected.\n  `--shared` is a shorthand for `--channel-id all` and still uses run-scoped mailbox send.\n  For human-authored markdown, mention teammates inline with raw `@member_id` tokens in the text body. The frontend should resolve those stable ids into display names when rendering.\n  `--mention` and `--mention-actor-id` remain available for scripts or generated payloads that need explicit mention metadata without rewriting the visible text body.\n  In team runtime, omitting `--run-id` lets AgentHub try the current actor runtime scope first, then fall back to the unique active Team run for the current team when possible.\n  If multiple active Team runs exist, `actor send` will fail with concrete candidate hints and require `--run-id`.\n  For human-visible shared progress updates that should not require explicit `run_id`, prefer `agenthub actor team-task-note --shared-thread ...`.\n".to_string(),
        ACTOR_HELP_TOPIC_PERMISSION_REVIEW_RESPOND => "Usage:\n  agenthub actor permission-review-respond --permission-id <id> [--permission-id <id> ...] [--team-id <team_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--option-id <option_id> | --outcome cancelled]\n\nExamples:\n  agenthub actor permission-review-respond --permission-id <id> --option-id allow\n  agenthub actor permission-review-respond --permission-id <id> --option-id approved-for-session\n  agenthub actor permission-review-respond --permission-id <id-1> --permission-id <id-2> --option-id allow\n  agenthub actor permission-review-respond --permission-id <id> --outcome cancelled\n\nNotes:\n  This command is for the currently assigned reviewer only.\n  Repeating `--permission-id` processes the requests sequentially and returns a JSON array.\n  Persistent/session approvals are selected with the request-specific `--option-id` value; `--outcome` currently supports only `cancelled`.\n  In team runtime, review writes should go through local authority internal gRPC instead of direct sqlite writes.\n".to_string(),
        "team-members" => {
            "Usage:\n  agenthub actor team-members [--team-id <team_id>] [--run-id <run_id>]\n"
                .to_string()
        }
        "team-tasks" => "Usage:\n  agenthub actor [--json] team-tasks [--team-id <team_id>] [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--limit <n>] [--status <all|open|in_progress|waiting|in_review|completed|canceled>] [--task-id <task_id>] [--assigned-member-id <member_id>] [--topic <topic>] [--include-shared-thread]\n\nNotes:\n  `--run-id` resolves the Team scope from a concrete execution when you do not want to pass `--team-id` explicitly.\n  `--task-id`, `--assigned-member-id`, and `--topic` are exact-match filters.\n".to_string(),
        "team-task-create" => "Usage:\n  agenthub actor [--json] team-task-create --title <title> [--team-id <team_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--status <open|in_progress|waiting|in_review|completed|canceled>] [--topic <topic>] [--context-json <json> | --context-json-file <path>]\n".to_string(),
        "team-task-show" => "Usage:\n  agenthub actor [--json] team-task-show --task-id <task_id> [--team-id <team_id>] [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--message-limit <n>]\n\nAliases:\n  `agenthub actor team-task-get ...`\n\nNotes:\n  Returns task metadata, conversation topic, latest linked run, and recent task messages.\n".to_string(),
        "team-task-update" => "Usage:\n  agenthub actor [--json] team-task-update --task-id <task_id> [--task-id <task_id> ...] [--status <open|in_progress|waiting|in_review|completed|canceled>] [--assigned-member-id <member_id> | --unassign] [--context-json <json> | --context-json-file <path> | --context-file <path> | --context-merge-json <json> | --context-merge-json-file <path> | --context-merge-file <path>] [--team-id <team_id>] [--actor-id <actor_id> | --agent-id <agent_id>]\n\nNotes:\n  Repeating `--task-id` applies the same patch to multiple tasks and returns a JSON/TOON array.\n  `assigned_member_id` means the member currently owning execution responsibility for the task.\n  `--context-json` replaces the entire context; `--context-merge-json` deep-merges into the existing object.\n  `--context-file` and `--context-merge-file` are short aliases for the corresponding JSON file flags.\n".to_string(),
        "team-task-note" => "Usage:\n  agenthub actor [--json] team-task-note (--task-id <task_id> | --shared-thread) [--kind <comment|decision|result>] --text <markdown> [--team-id <team_id>] [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>]\n\nNotes:\n  Appends an immutable note to the task conversation instead of overwriting task metadata.\n  Use `comment` for discussion, `decision` for planning decisions, and `result` for outcome/evidence updates.\n  `--shared-thread` targets the canonical `all` thread for the resolved team scope and does not require an explicit task id.\n".to_string(),
        ACTOR_HELP_TOPIC_TEAM_THREAD_OPEN => "Usage:\n  agenthub actor [--json] team-thread-open --root-message-id <message_id> [--channel-id <channel_id> | --shared] [--team-id <team_id>] [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>]\n\nExamples:\n  agenthub actor team-thread-open --shared --root-message-id 42\n  agenthub actor team-thread-open --team-id <team_id> --channel-id review --root-message-id 105\n\nSummary-first flow:\n  1. Post a concise summary root in the channel.\n  2. Call `agenthub actor team-thread-open ...` for that root message.\n  3. Continue detailed context, logs, and evidence with `team-thread-reply`.\n\nNotes:\n  This is a Team actor capability, not just a UI hint.\n  The root message must already exist in the target Team channel.\n  `--shared` is shorthand for `--channel-id all`.\n  The current implementation returns a stable thread reference anchored to `root_message_id`.\n  Passive readers of the root message are not automatically enrolled as thread participants; later thread forwarding goes to existing thread participants, members mentioned on the root message, members mentioned on earlier thread replies, and newly mentioned members in the current reply.\n".to_string(),
        ACTOR_HELP_TOPIC_TEAM_THREAD_REPLY => "Usage:\n  agenthub actor [--json] team-thread-reply --root-message-id <message_id> (--text <markdown> | --text-file <path>) [--channel-id <channel_id> | --shared] [--team-id <team_id>] [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>]\n\nExamples:\n  agenthub actor team-thread-reply --shared --root-message-id 42 --text \"I agree with this point\"\n  agenthub actor team-thread-reply --team-id <team_id> --channel-id review --root-message-id 105 --text-file reply.md\n\nNotes:\n  This appends a thread-scoped reply anchored to an existing channel message.\n  The reply is still stored in the channel conversation and carries `thread_root_message_id` metadata for thread filtering.\n  `--shared` is shorthand for `--channel-id all`.\n  Thread reply mailbox forwarding targets existing thread participants, members mentioned on the root message, members mentioned on earlier thread replies, and newly mentioned members in the current reply. A teammate who only saw the root summary earlier still will not receive the thread reply automatically unless they already match one of those participant or mention paths.\n".to_string(),
        "team-step-decision" => "Usage:\n  agenthub actor [--json] team-step-decision --step-id <step_id> [--decision-json <json> | --decision-json-file <path>] [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--runtime-handle-id <session_id>]\n\nDecision schema:\n  {\n    \"action\": \"continue|complete|input_required|resume|fail|start\",\n    \"output\": {...},\n    \"input\": {...},\n    \"reason\": \"...\",\n    \"error_text\": \"...\"\n  }\n\nExamples:\n  agenthub actor team-step-decision --step-id <step_id>\n  agenthub actor team-step-decision --step-id <step_id> --decision-json '{\"action\":\"continue\",\"output\":{\"summary\":\"need another round\"}}'\n  agenthub actor team-step-decision --step-id <step_id> --decision-json-file .agenthubmemory/step-decision.json\n\nNotes:\n  When no explicit decision payload is provided, the command reads `.agenthubmemory/step-decision.json` from the current workspace.\n  This is a thin wrapper over `team-step-transition` for worker-friendly structured round decisions.\n  `runtime_handle_id` may still be provided explicitly for `start` when the worker/runtime needs to bind the step to a new session id.\n".to_string(),
        "team-step-transition" => "Usage:\n  agenthub actor [--json] team-step-transition --step-id <step_id> --action <start|continue|complete|input_required|resume|fail> [--run-id <run_id>] [--actor-id <actor_id> | --agent-id <agent_id>] [--runtime-handle-id <session_id>] [--output-json <json> | --output-json-file <path>] [--input-json <json> | --input-json-file <path>] [--reason <text> | --reason-file <path>] [--error-text <text> | --error-text-file <path>]\n\nExamples:\n  agenthub actor team-step-transition --step-id <step_id> --action continue --output-json '{\"summary\":\"need another round\"}'\n  agenthub actor team-step-transition --step-id <step_id> --action input_required --reason \"need human decision\" --input-json '{\"question\":\"approve?\"}'\n  agenthub actor team-step-transition --step-id <step_id> --action complete --output-json-file .agenthubmemory/round-result.json\n\nNotes:\n  `team-step-transition` uses the current actor runtime scope when `--run-id` is omitted, then falls back to Team run inference like other direct run-scoped commands.\n  Worker tokens may transition only their own assigned steps; coordinator/orchestrator tokens may transition any step within scope.\n  `continue` is intended for `reconcile_loop` rounds and keeps the step in `working` while advancing to the next round.\n".to_string(),
        "time-trigger-set" => "Usage:\n  agenthub actor time-trigger-set --delay-seconds <seconds> --message <text> [--actor-id <actor_id> | --agent-id <agent_id>]\n".to_string(),
        "time-trigger-list" => "Usage:\n  agenthub actor time-trigger-list [--actor-id <actor_id> | --agent-id <agent_id>] [--limit <n>]\n".to_string(),
        "time-trigger-cancel" => "Usage:\n  agenthub actor time-trigger-cancel --trigger-id <trigger_id> [--actor-id <actor_id> | --agent-id <agent_id>]\n".to_string(),
        _ => actor_usage(),
    }
}
